    rs=sorted(div); cs=sorted(dcol)
    # split indices
    def bounds(idx, others):
        prev=[x for x in others if x<idx]
        nxt=[x for x in others if x>idx]
        lo=-1 if not prev else prev[-1]+1
        hi=H if not nxt else nxt[0]-1
        return lo,hi
    for r in rs:
        lo,hi=bounds(r,rs); 
        for c in list(dcol):
            if lo<=c<=hi: out[r][c]=None   # marker will overwrite later
    # find blocks: contiguous ranges of rows between divider rows, cols between divider cols
