from collections import Counter, defaultdict

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def solve(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    dr=[r for r in range(H) if len(set(g[r]))==1 and next(iter(set(g[r])))!=bg]
    dc=[c for c in range(W) if len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=bg]
    def segs(divs,n):
        s=-1; res=[]
        for p in [-1]+divs+[n]:
            if p>s: res.append((s+1,p-1))
            s=p
        return res
    rs=segs(dr,H); cs=segs(dc,W)
    BCG=defaultdict(int)
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v!=bg and i not in dr and j not in dc:
                BCG[(sum(1 for d in dr if d<i),sum(1 for d in dc if d<j))]+=1
    (bidx,cidx),cnt=max(((k,v) for k,v in BCG.items()),key=lambda kv:kv[1])
    rb=[a for a,(x,y) in enumerate(rs) if x<=bidx<y][0]
    rc=[a for a,(x,y) in enumerate(cs) if x<=cidx<y][0]
    r0,r1=rs[rb]; c0,c1=cs[rc]
    mark=Counter(g[i][j] for i in range(r0,r1) for j in range(c0,c1) if g[i][j]!=bg).most_common(1)[0][0]
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if i in dr or j in dc: continue
            bi=sum(1 for d in dr if d<i); bj=sum(1 for d in dc if d<j)
            if (bi,bj)==(rb,rc): out[i][j]=mark
            else: out[i][j]=bg
    return out
print('demo1:',solve(G['Demo pair 1 input'])==G['Demo pair 1 output'])
