            pos=[(i,j,g[i][j]) for i in range(r0,r1) for j in range(c0,c1) if g[i][j]!=bg]
            blk[(bi,bj)]=(pos,len(pos))
    mx=max(cnt for _,cnt in blk.values())
    wins=[kk for kk,(pos,cnt) in blk.items() if cnt==mx]
    marks=set()
    for kk in wins:
        for i,j,v in blk[kk][0]: marks.add(v)
    mark=marks.pop() if len(marks)==1 else 9
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if i in dr or j in dc: continue
            bi=sum(1 for d in dr if d<i); bj=sum(1 for d in dc if d<j)
            if (bi,bj) in wins: out[i][j]=mark
            else: out[i][j]=bg
    return out
for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4','Demo pair 5']:
    print(k, solve(G[k+' input'])==G[k+' output'])
